from decimal import Decimal
from typing import Any


def _string_value(value: Any) -> str:
    return "" if value is None else str(value)


def _line_number(value: Any) -> Decimal:
    text = _string_value(value).strip()
    if text == "":
        return Decimal(0)
    return Decimal(text)


def renumber(lines: list[dict]) -> list[dict]:
    grouped: dict[str, list[tuple[int, dict]]] = {}

    for position, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = _string_value(row.get("ORD_ID", ""))
        grouped.setdefault(order_id, []).append((position, row))

    result: list[dict] = []

    for order_id in sorted(grouped):
        rows = grouped[order_id]
        rows.sort(key=lambda item: (_line_number(item[1].get("LINE_NO", "")), item[0]))

        for new_line_no, (_, row) in enumerate(rows, start=1):
            migrated_row = dict(row)
            migrated_row["LINE_NO"] = new_line_no
            result.append(migrated_row)

    return result
